from odoo import fields, models
from odoo.exceptions import UserError


class AccountMove(models.Model):
    """A journal entry generated by payroll stays what payroll made it."""

    _inherit = 'account.move'

    liwan_payroll_origin = fields.Selection(
        [('run', 'Payroll run'), ('payment', 'Payroll payment'), ('eos_provision', 'End of service provision')],
        string='Payroll origin', copy=False, readonly=True, index='btree_not_null',
        help='What generated the entry, like origin_payment_id for a payment entry.',
    )

    def _liwan_refuse_payroll_change(self):
        if self.filtered('liwan_payroll_origin'):
            raise UserError(self.env._('A journal entry generated by payroll cannot be reset, cancelled or deleted.'))

    def button_draft(self):
        self._liwan_refuse_payroll_change()
        return super().button_draft()

    def button_cancel(self):
        self._liwan_refuse_payroll_change()
        return super().button_cancel()

    def unlink(self):
        self._liwan_refuse_payroll_change()
        return super().unlink()


class AccountPartialReconcile(models.Model):
    """The match between a payroll entry's salaries payable and its salary payment stays as payroll made it.

    The run is ``paid`` because of that match; removing it would reopen the payable while the run still reads
    paid. Every unreconcile path (an entry's, a payment's) goes through this unlink.
    """

    _inherit = 'account.partial.reconcile'

    def unlink(self):
        payroll = (self.debit_move_id | self.credit_move_id).move_id.filtered(
            lambda move: move.liwan_payroll_origin in ('run', 'payment'),
        )
        if payroll:
            raise UserError(self.env._('The salary payment of a payroll run cannot be unreconciled.'))
        return super().unlink()
